package org.humanjourney.core.fishing;
import com.google.gson.*;
import net.minecraft.util.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.packs.resources.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
class FishingTest {
    final FishingPolicy policy=new FishingPolicy(20,60,5);
    JsonObject json(){return JsonParser.parseString("{\"schema_version\":1,\"bite_time\":{\"minimum_seconds\":20,\"maximum_seconds\":60,\"lure_reduction_seconds_per_level\":5}}").getAsJsonObject();}
    @AfterEach void reset(){FishingBalance.reset();}
    @Test void exampleParsesAndDefinesTwentyToSixtySeconds()throws Exception{var root=Path.of(System.getProperty("humanjourney.projectDir"));assertEquals(policy,FishingPolicy.parse(JsonParser.parseString(Files.readString(root.resolve("example-fishing-datapack/data/human_journey/core/fishing.json")))));assertEquals(new FishingPolicy.Bounds(400,1200),policy.bounds(0));}
    @Test void invertedNegativeZeroAndUnboundedRangesAreRejected(){for(int[] v:new int[][]{{61,60,5},{-1,60,5},{0,60,5},{20,-1,5},{20,3601,5},{20,60,-1},{20,60,3601}})assertThrows(IllegalArgumentException.class,()->new FishingPolicy(v[0],v[1],v[2]));}
    @Test void malformedSchemaTypesUnknownAndMissingFieldsAreRejected(){for(String field:List.of("schema_version","bite_time")){var j=json();j.remove(field);assertThrows(IllegalArgumentException.class,()->FishingPolicy.parse(j));}for(JsonElement value:List.of(new JsonPrimitive(2),new JsonPrimitive("1"),JsonNull.INSTANCE)){var j=json();j.add("schema_version",value);assertThrows(IllegalArgumentException.class,()->FishingPolicy.parse(j));}for(JsonElement value:List.of(new JsonPrimitive(-1),new JsonPrimitive(20.1),new JsonPrimitive("20"),new JsonPrimitive(1e100),JsonNull.INSTANCE)){var j=json();j.getAsJsonObject("bite_time").add("minimum_seconds",value);assertThrows(IllegalArgumentException.class,()->FishingPolicy.parse(j));}var unknown=json();unknown.addProperty("loot",true);assertThrows(IllegalArgumentException.class,()->FishingPolicy.parse(unknown));var invalid=json();invalid.getAsJsonObject("bite_time").addProperty("typo",1);assertThrows(IllegalArgumentException.class,()->FishingPolicy.parse(invalid));}
    @Test void lureOneTwoThreeUseNativeFishingEffectTicks(){for(int level=0;level<=3;level++)assertEquals(new FishingPolicy.Bounds((20-5*level)*20,(60-5*level)*20),policy.bounds(level*100));}
    @Test void configurableReductionAndNonstandardNativeEffectsAreScaled(){assertEquals(new FishingPolicy.Bounds(320,1120),new FishingPolicy(20,60,2).bounds(200));assertEquals(new FishingPolicy.Bounds(350,1150),policy.bounds(50));assertEquals(new FishingPolicy.Bounds(400,1200),new FishingPolicy(20,60,0).bounds(999));}
    @Test void lowerBoundAndExtremeEnchantmentsRemainPositiveAndOrdered(){assertEquals(new FishingPolicy.Bounds(1,1),policy.bounds(Integer.MAX_VALUE));assertEquals(new FishingPolicy.Bounds(1,100),policy.bounds(1100));assertEquals(new FishingPolicy.Bounds(400,1200),policy.bounds(-100));}
    @Test void lastValidPolicySurvivesRejectionAndMissingReturnsToVanilla(){FishingBalance.accept(policy,"test pack");var valid=FishingBalance.state();FishingBalance.reject("bad schema");assertSame(policy,FishingBalance.state().policy());assertEquals(valid.revision(),FishingBalance.state().revision());assertEquals(valid.lastSuccess(),FishingBalance.state().lastSuccess());assertTrue(FishingBalance.describe().contains("REJECTED"));FishingBalance.missing();assertNull(FishingBalance.state().policy());assertTrue(FishingBalance.describe().contains("vanilla"));}
    @Test void missingPolicyPreservesNativeDrawAndRandomSequence(){assertNull(FishingBalance.state().policy());for(int lure:new int[]{0,100,200,300}){var expected=RandomSource.create(19);var actual=RandomSource.create(19);for(int i=0;i<100;i++)assertEquals(Mth.nextInt(expected,100,600)-lure,FishingTiming.initialDraw(actual,100,600,lure)-lure);assertEquals(expected.nextLong(),actual.nextLong());}}
    @Test void enabledDrawCompensatesNativeSubtractionExactlyOnce(){FishingBalance.accept(policy,"test");for(int lure:new int[]{0,100,200,300,Integer.MAX_VALUE}){var expected=RandomSource.create(33);var actual=RandomSource.create(33);var bounds=policy.bounds(lure);for(int i=0;i<100;i++){int result=FishingTiming.initialDraw(actual,100,600,lure)-lure;assertEquals(Mth.nextInt(expected,bounds.minimumTicks(),bounds.maximumTicks()),result);assertTrue(result>=bounds.minimumTicks()&&result<=bounds.maximumTicks());}assertEquals(expected.nextLong(),actual.nextLong());}}
    final PreparableReloadListener.PreparationBarrier barrier=new PreparableReloadListener.PreparationBarrier(){public <T> CompletableFuture<T> wait(T value){return CompletableFuture.completedFuture(value);}};
    @Test void realReloadListenerHandlesMissingInvalidAndSuccessfulResources()throws Exception{
        var manager=mock(ResourceManager.class);var id=ResourceLocation.parse("human_journey:core/fishing.json");var resource=mock(Resource.class);when(resource.sourcePackId()).thenReturn("test pack");when(manager.getResource(id)).thenReturn(Optional.of(resource));when(resource.openAsReader()).thenAnswer(i->new java.io.BufferedReader(new java.io.StringReader(json().toString())));var listener=new FishingReloadListener();listener.reload(barrier,manager,Runnable::run,Runnable::run).join();assertEquals(policy,FishingBalance.state().policy());var valid=FishingBalance.state();when(resource.openAsReader()).thenAnswer(i->new java.io.BufferedReader(new java.io.StringReader("{\"schema_version\":9}")));listener.reload(barrier,manager,Runnable::run,Runnable::run).join();assertEquals(valid.policy(),FishingBalance.state().policy());assertEquals(valid.revision(),FishingBalance.state().revision());when(manager.getResource(id)).thenReturn(Optional.empty());listener.reload(barrier,manager,Runnable::run,Runnable::run).join();assertNull(FishingBalance.state().policy());
    }
    ClassNode read(String name)throws Exception{try(var in=getClass().getClassLoader().getResourceAsStream(name+".class")){assertNotNull(in);var c=new ClassNode();new ClassReader(in).accept(c,0);return c;}}
    @Test void exactFishingHookBytecodeMatchesSingleRedirectContract()throws Exception{
        var c=read("net/minecraft/world/entity/projectile/FishingHook");assertTrue(c.fields.stream().anyMatch(f->f.name.equals("lureSpeed")&&f.desc.equals("I")&&(f.access&Opcodes.ACC_FINAL)!=0));var m=c.methods.stream().filter(x->x.name.equals("catchingFish")&&x.desc.equals("(Lnet/minecraft/core/BlockPos;)V")).findFirst().orElseThrow();List<MethodInsnNode> draws=new ArrayList<>();for(var insn:m.instructions)if(insn instanceof MethodInsnNode call&&call.owner.equals("net/minecraft/util/Mth")&&call.name.equals("nextInt"))draws.add(call);assertEquals(3,draws.size());var last=draws.get(2);assertEquals(600,((IntInsnNode)last.getPrevious()).operand);assertEquals(100,((IntInsnNode)last.getPrevious().getPrevious()).operand);
        var cursor=last.getNext();assertTrue(cursor instanceof FieldInsnNode f&&f.getOpcode()==Opcodes.PUTFIELD&&f.name.equals("timeUntilLured"));cursor=cursor.getNext();while(cursor!=null&&!(cursor instanceof FieldInsnNode f&&f.name.equals("lureSpeed")))cursor=cursor.getNext();assertNotNull(cursor);assertEquals(Opcodes.ISUB,cursor.getNext().getOpcode());assertTrue(cursor.getNext().getNext() instanceof FieldInsnNode f&&f.name.equals("timeUntilLured"));
        var mixin=read("org/humanjourney/core/fishing/mixin/FishingHookMixin");assertEquals(1,mixin.methods.stream().filter(x->!x.name.equals("<init>")).count());var method=mixin.methods.stream().filter(x->x.name.startsWith("hjcore$")).findFirst().orElseThrow();var annotations=new ArrayList<AnnotationNode>();if(method.visibleAnnotations!=null)annotations.addAll(method.visibleAnnotations);if(method.invisibleAnnotations!=null)annotations.addAll(method.invisibleAnnotations);var redirect=annotations.stream().filter(a->a.desc.endsWith("/Redirect;")).findFirst().orElseThrow();assertTrue(redirect.values.toString().contains("catchingFish(Lnet/minecraft/core/BlockPos;)V"));assertFalse(redirect.values.toString().contains("retrieve"));
    }
    @Test void nativeLureEffectAndFishingLootResourcesRemainUntouched()throws Exception{
        try(var in=getClass().getClassLoader().getResourceAsStream("data/minecraft/enchantment/lure.json")){assertNotNull(in);var lure=JsonParser.parseReader(new java.io.InputStreamReader(in)).getAsJsonObject();var value=lure.getAsJsonObject("effects").getAsJsonArray("minecraft:fishing_time_reduction").get(0).getAsJsonObject().getAsJsonObject("effect").getAsJsonObject("value");assertEquals(5,value.get("base").getAsInt());assertEquals(5,value.get("per_level_above_first").getAsInt());}
        Path root=Path.of(System.getProperty("humanjourney.projectDir"));for(Path dir:List.of(root.resolve("src/main/resources"),root.resolve("example-fishing-datapack")))try(var paths=Files.walk(dir)){assertFalse(paths.anyMatch(p->p.toString().contains("loot_table")||p.toString().contains("enchantment/")));}
    }
}
